mapper.select:
SELECT id, name, customer_id, opportunity_id, owner, amount, start_date, end_date, signed_date, status, remark, pos,
       organization_id, create_user, update_user, create_time, update_time
FROM crm_contract
WHERE organization_id = #{organizationId}

    AND name LIKE CONCAT('%', #{keyword}, '%')


    AND status = #{status}


    AND customer_id = #{customerId}

ORDER BY create_time DESC
